from io import StringIO
import csv

def render(rows, settings):
    output = StringIO()
    writer = csv.writer(output, delimiter=settings["delimiter"])
    if settings["include_header"]:
        writer.writerow(settings["columns"])
    writer.writerows([row[column] for column in settings["columns"]] for row in rows)
    return output.getvalue()

